COMMENT ON TABLE sales.orders IS 'One row per customer order. Amounts in USD, tax excluded.';
COMMENT ON COLUMN sales.orders.status IS 'open, shipped, or cancelled. Exclude cancelled from revenue.';

-- Read the comments back when you build the NL-to-SQL prompt
SELECT obj_description('sales.orders'::regclass, 'pg_class');
SELECT col_description('sales.orders'::regclass, a.attnum), a.attname
FROM pg_attribute a
WHERE a.attrelid = 'sales.orders'::regclass AND a.attnum > 0;

COMMENT ON TABLE hn.hacker_news IS 'Hacker News stories and comments, one row per item.';
COMMENT ON COLUMN hn.hacker_news.url IS 'Story link. Use the host part as the domain.';

-- Generate SQL over the current database (MotherDuck SQL assistant)
CALL prompt_sql('what are the top domains being shared on hacker_news?');
